/**
 * Servidor local (PLAN §3). Bindea SOLO a 127.0.0.1:8081 — sin auth, sin
 * exposicion. Ingesta incremental al arrancar y expone /api/summary. Sirve el
 * build del frontend desde web/dist si existe.
 */
import Fastify from "fastify";
import fastifyStatic from "@fastify/static";
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { existsSync } from "node:fs";
import { openDb, defaultDbPath } from "./lib/db.js";
import { ingestAll } from "./ingest.js";
import { loadPricing, savePricing, type Pricing } from "./lib/pricing.js";
import { getSummary } from "./lib/summary.js";
import { loadConfig, saveConfig, type Config } from "./lib/config.js";
import { discoverCatalog, getSkills } from "./lib/skills.js";
import { scanMemory } from "./lib/memory.js";
import { getActivity, getSessionDetail } from "./lib/activity.js";

const HOST = "127.0.0.1";
const PORT = 8081;

export async function buildServer() {
  const db = openDb(defaultDbPath());
  // Estado mutable: pricing/config se pueden editar desde Configuracion.
  let pricing: Pricing = await loadPricing();
  let config: Config = await loadConfig();
  const catalog = await discoverCatalog(); // read-only, una vez al arrancar

  const app = Fastify({ logger: false });

  app.get("/api/health", async () => ({ ok: true }));

  app.get("/api/summary", async (req) => {
    const q = req.query as { windowDays?: string };
    const windowDays = q.windowDays ? Number(q.windowDays) : undefined;
    return getSummary(db, pricing, { windowDays });
  });

  app.get("/api/skills", async () => getSkills(db, config, catalog));

  app.get("/api/memory", async () => scanMemory(undefined, { staleDays: config.staleDays }));

  app.get("/api/activity", async () => getActivity(db));

  app.get("/api/session/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const detail = getSessionDetail(db, id);
    if (!detail) {
      reply.code(404);
      return { error: "sesión no encontrada" };
    }
    return detail;
  });

  app.get("/api/config", async () => config);
  app.put("/api/config", async (req) => {
    config = await saveConfig(req.body as Partial<Config>);
    return config;
  });

  app.get("/api/pricing", async () => pricing);
  app.put("/api/pricing", async (req, reply) => {
    try {
      pricing = await savePricing(req.body as Pricing);
      return { ok: true, pricing, note: "rebuild para recalcular costos ya ingeridos" };
    } catch (err) {
      reply.code(400);
      return { ok: false, error: (err as Error).message };
    }
  });

  app.post("/api/rebuild", async () => ingestAll(db, { pricing }));

  const here = dirname(fileURLToPath(import.meta.url));
  const dist = join(here, "..", "web", "dist");
  if (existsSync(dist)) {
    app.register(fastifyStatic, { root: dist });
  }

  app.addHook("onClose", async () => db.close());
  return { app, db, pricing, config };
}

async function main() {
  const { app, db, pricing, config } = await buildServer();

  // Ingesta incremental al arrancar (fuentes read-only).
  const summary = await ingestAll(db, { pricing, staleDays: config.staleDays });
  console.log(
    `Ingesta: ${summary.files} archivos · ${summary.filesChanged} cambiados · ${summary.eventsInserted} eventos nuevos · ${summary.memories} memorias` +
      (summary.unknownModels.length ? ` · ${summary.unknownModels.length} modelos sin tarifa` : ""),
  );

  await app.listen({ host: HOST, port: PORT });
  console.log(`Motor agentico escuchando en http://${HOST}:${PORT}`);
}

// Arranca solo si se ejecuta directo (no al importar en tests).
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

/**
 * Ingesta incremental de transcripts hacia SQLite (PLAN §3).
 *  - Guarda por archivo cuantas lineas ya se leyeron (ingest_offsets).
 *  - Re-lee solo las lineas nuevas; la dedup cross-lectura la garantiza la PK
 *    dedup_key de usage_events (INSERT OR IGNORE).
 *  - Costo por evento se calcula en ingesta con el motor de Fase 1.
 * Fuentes = SOLO LECTURA (readFileRO + stat). Escritura solo en ./data.
 */
import { stat, unlink } from "node:fs/promises";
import { basename, join } from "node:path";
import type { DB } from "./lib/db.js";
import { openDb, defaultDbPath } from "./lib/db.js";
import { readFileRO } from "./lib/fs-readonly.js";
import {
  ClaudeCodeAdapter,
  defaultProjectsRoot,
  parseTranscriptLines,
  parseSkillUsages,
} from "./adapters/claude-code.js";
import { costForEvent } from "./lib/cost.js";
import { loadPricing, getRate, UnknownModels, type Pricing } from "./lib/pricing.js";
import { scanMemory } from "./lib/memory.js";

export interface IngestSummary {
  files: number;
  filesChanged: number;
  eventsInserted: number;
  memories: number;
  unknownModels: string[];
}

interface OffsetRow {
  size: number;
  mtime_ms: number;
  line_count: number;
}

async function ingestFile(
  db: DB,
  path: string,
  project: string,
  pricing: Pricing,
  unknown: UnknownModels,
): Promise<number> {
  const st = await stat(path);
  const sizeNow = st.size;
  const mtimeNow = Math.floor(st.mtimeMs);

  const prev = db
    .prepare("SELECT size, mtime_ms, line_count FROM ingest_offsets WHERE path = ?")
    .get(path) as OffsetRow | undefined;

  // Sin cambios (mismo tamano y mtime) => nada que hacer.
  if (prev && prev.size === sizeNow && prev.mtime_ms === mtimeNow) return 0;

  // Archivo reemplazado/truncado (mas chico que lo leido) => releer desde 0.
  const fromLine = prev && sizeNow >= prev.size ? prev.line_count : 0;

  const raw = await readFileRO(path);
  const { events, lineCount } = parseTranscriptLines(raw, fromLine);
  const skillUsages = parseSkillUsages(raw, fromLine);

  const sessionId = basename(path, ".jsonl");

  const insertEvent = db.prepare(`
    INSERT OR IGNORE INTO usage_events
      (dedup_key, session_id, ts, day, model,
       input_tokens, output_tokens, cache_write_tokens, cache_read_tokens, cost_usd)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);
  const insertSkill = db.prepare(`
    INSERT OR IGNORE INTO skills_usage (skill, session_id, ts, kind) VALUES (?, ?, ?, ?)
  `);

  let inserted = 0;
  const run = db.prepare("BEGIN");
  run.run();
  try {
    for (const su of skillUsages) {
      insertSkill.run(su.skill, sessionId, su.ts, su.kind);
    }
    for (const { dedupKey, event } of events) {
      const rate = getRate(pricing, event.model, unknown);
      const cost = costForEvent(event, rate);
      const res = insertEvent.run(
        dedupKey,
        sessionId,
        event.ts,
        event.day,
        event.model,
        event.input,
        event.output,
        event.cacheWrite,
        event.cacheRead,
        cost,
      );
      if (res.changes > 0) inserted++;
    }

    // Recalcula agregados de la sesion desde la DB (idempotente).
    const agg = db
      .prepare(
        "SELECT COUNT(*) AS turns, MIN(ts) AS started, MAX(ts) AS ended FROM usage_events WHERE session_id = ?",
      )
      .get(sessionId) as { turns: number; started: string | null; ended: string | null };

    db.prepare(`
      INSERT INTO sessions (id, agent, project, started_at, ended_at, turns)
      VALUES (?, 'claude-code', ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        project = excluded.project,
        started_at = excluded.started_at,
        ended_at = excluded.ended_at,
        turns = excluded.turns
    `).run(sessionId, project, agg.started, agg.ended, agg.turns);

    db.prepare(`
      INSERT INTO ingest_offsets (path, size, mtime_ms, line_count, updated_at)
      VALUES (?, ?, ?, ?, ?)
      ON CONFLICT(path) DO UPDATE SET
        size = excluded.size, mtime_ms = excluded.mtime_ms,
        line_count = excluded.line_count, updated_at = excluded.updated_at
    `).run(path, sizeNow, mtimeNow, lineCount, new Date().toISOString());

    db.prepare("COMMIT").run();
  } catch (err) {
    db.prepare("ROLLBACK").run();
    throw err;
  }

  return inserted;
}

/** Ingesta todos los transcripts descubiertos hacia `db`. */
export async function ingestAll(
  db: DB,
  opts: { projectsRoot?: string; pricing?: Pricing; staleDays?: number } = {},
): Promise<IngestSummary> {
  const root = opts.projectsRoot ?? defaultProjectsRoot();
  const adapter = new ClaudeCodeAdapter(root);
  const pricing = opts.pricing ?? (await loadPricing());
  const unknown = new UnknownModels();

  const paths = await adapter.discoverSessions();
  let eventsInserted = 0;
  let filesChanged = 0;

  for (const path of paths) {
    const project = basename(join(path, ".."));
    const inserted = await ingestFile(db, path, project, pricing, unknown);
    if (inserted > 0) filesChanged++;
    eventsInserted += inserted;
  }

  const memories = await refreshMemoryNodes(db, root, opts.staleDays);

  return {
    files: paths.length,
    filesChanged,
    eventsInserted,
    memories,
    unknownModels: unknown.list(),
  };
}

/** Reconstruye memory_nodes (snapshot) desde los archivos de memoria (RO). */
async function refreshMemoryNodes(db: DB, projectsRoot: string, staleDays?: number): Promise<number> {
  const graph = await scanMemory(projectsRoot, { staleDays });
  const memNodes = graph.nodes.filter((n) => n.kind === "memory" || n.kind === "index");
  const origin = new Map<string, string>();
  for (const l of graph.links) {
    if (l.rel === "origin") origin.set(l.source, l.target.replace(/^session:/, ""));
  }
  db.prepare("BEGIN").run();
  try {
    db.prepare("DELETE FROM memory_nodes").run();
    const ins = db.prepare(`
      INSERT OR REPLACE INTO memory_nodes
        (path, name, project, type, size, last_touched, origin_session, stale_bool)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    for (const n of memNodes) {
      ins.run(n.id, n.label, n.project, n.type ?? n.kind, n.size ?? 0, n.lastTouched ?? null, origin.get(n.id) ?? null, n.stale ? 1 : 0);
    }
    db.prepare("COMMIT").run();
  } catch (err) {
    db.prepare("ROLLBACK").run();
    throw err;
  }
  return graph.counts.memories;
}

/** Borra la DB (cache reconstruible) y reingesta todo desde cero. */
export async function rebuild(
  opts: { dbPath?: string; projectsRoot?: string } = {},
): Promise<IngestSummary> {
  const dbPath = opts.dbPath ?? defaultDbPath();
  for (const f of [dbPath, `${dbPath}-wal`, `${dbPath}-shm`]) {
    await unlink(f).catch(() => {}); // puede no existir
  }
  const db = openDb(dbPath);
  try {
    return await ingestAll(db, { projectsRoot: opts.projectsRoot });
  } finally {
    db.close();
  }
}

/** Entry: borra ./data/motor.db y reingesta todo (PLAN §1.3, comando `rebuild`). */
import { rebuild } from "./ingest.js";

const t0 = Date.now();
const summary = await rebuild();
const secs = ((Date.now() - t0) / 1000).toFixed(1);
console.log(
  `rebuild: ${summary.files} archivos · ${summary.eventsInserted} eventos · ${summary.memories} memorias · ${secs}s` +
    (summary.unknownModels.length
      ? `\n⚠ ${summary.unknownModels.length} modelos sin tarifa: ${summary.unknownModels.join(", ")}`
      : ""),
);

/**
 * CLI Fase 1: descubre transcripts de Claude Code (SOLO LECTURA), agrega por
 * dia/modelo e imprime la tabla de gasto "equivalente API" (PLAN §2, §6-F1).
 *
 *   npm run cli            # usa ~/.claude/projects
 *   npm run cli -- <root>  # usa otra raiz de projects
 */
import { ClaudeCodeAdapter, defaultProjectsRoot } from "./adapters/claude-code.js";
import { loadPricing } from "./lib/pricing.js";
import { aggregate, type Row } from "./lib/aggregate.js";
import type { NormalizedSession } from "./adapters/types.js";

function fmtInt(n: number): string {
  return n.toLocaleString("en-US");
}
function fmtUsd(n: number): string {
  return `$${n.toFixed(2)}`;
}

function pad(s: string, w: number, right = false): string {
  return right ? s.padStart(w) : s.padEnd(w);
}

function printTable(rows: Row[], total: Aggregated["total"]): void {
  const headers = ["DIA", "MODELO", "in", "out", "cache-w", "cache-r", "$ equiv-API"];
  const data = rows.map((r) => [
    r.day,
    r.model,
    fmtInt(r.input),
    fmtInt(r.output),
    fmtInt(r.cacheWrite),
    fmtInt(r.cacheRead),
    fmtUsd(r.costUsd),
  ]);
  const totalRow = [
    "TOTAL",
    "",
    fmtInt(total.input),
    fmtInt(total.output),
    fmtInt(total.cacheWrite),
    fmtInt(total.cacheRead),
    fmtUsd(total.costUsd),
  ];

  const all = [headers, ...data, totalRow];
  const widths = headers.map((_, c) => Math.max(...all.map((row) => row[c].length)));
  const rightAlign = [false, false, true, true, true, true, true];

  const renderRow = (row: string[]) =>
    row.map((cell, c) => pad(cell, widths[c], rightAlign[c])).join("  ");

  const sep = widths.map((w) => "-".repeat(w)).join("  ");

  console.log(renderRow(headers));
  console.log(sep);
  for (const row of data) console.log(renderRow(row));
  console.log(sep);
  console.log(renderRow(totalRow));
}

type Aggregated = ReturnType<typeof aggregate>;

async function main(): Promise<void> {
  const root = process.argv[2] ?? defaultProjectsRoot();
  const adapter = new ClaudeCodeAdapter(root);
  const pricing = await loadPricing();

  const paths = await adapter.discoverSessions();
  const sessions: NormalizedSession[] = [];
  for (const p of paths) {
    try {
      sessions.push(await adapter.parseSession(p));
    } catch (err) {
      console.error(`! no se pudo parsear ${p}: ${(err as Error).message}`);
    }
  }

  const { rows, total, unknownModels } = aggregate(sessions, pricing);

  const eventCount = sessions.reduce((n, s) => n + s.events.length, 0);
  console.log(
    `Transcripts: ${paths.length} archivos · ${sessions.length} sesiones · ${eventCount} eventos de uso`,
  );
  console.log("Costos = equivalente API (tarifa medida; no lo que pagas por suscripcion)\n");

  if (rows.length === 0) {
    console.log("(sin eventos de uso)");
  } else {
    printTable(rows, total);
  }

  if (unknownModels.length > 0) {
    console.log(
      `\n⚠ ${unknownModels.length} modelos sin tarifa (costo 0): ${unknownModels.join(", ")}`,
    );
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { extractUsageEvents, ClaudeCodeAdapter } from "../src/adapters/claude-code.js";

const here = dirname(fileURLToPath(import.meta.url));
const fx = (name: string) => join(here, "fixtures", name);
const read = (name: string) => readFileSync(fx(name), "utf8");

describe("extractUsageEvents", () => {
  const events = extractUsageEvents(read("deterministic.jsonl"));

  it("dedup: un mismo (message.id + requestId) triplicado cuenta una vez", () => {
    const msgA = events.filter((e) => e.model === "claude-opus-4-8" && e.day === "2026-07-01");
    expect(msgA).toHaveLength(1);
  });

  it("excluye eventos con model <synthetic>", () => {
    expect(events.some((e) => e.model === "<synthetic>")).toBe(false);
  });

  it("salta lineas corruptas sin lanzar y conserva modelos desconocidos", () => {
    // ghost sigue siendo un evento (el precio se decide despues, no aqui)
    expect(events.some((e) => e.model === "claude-ghost-9")).toBe(true);
  });

  it("total de eventos unicos esperado = 4 (opus d1, haiku d1, ghost d1, opus d2)", () => {
    expect(events).toHaveLength(4);
  });

  it("deriva day = YYYY-MM-DD del timestamp", () => {
    expect(new Set(events.map((e) => e.day))).toEqual(new Set(["2026-07-01", "2026-07-02"]));
  });
});

describe("archivo sin usage", () => {
  it("devuelve [] sin lanzar (assistant sin usage + user + queue-operation)", () => {
    expect(extractUsageEvents(read("zero-usage.jsonl"))).toEqual([]);
  });
});

describe("fixtures reales anonimizados", () => {
  for (const name of ["real-printer-android.jsonl", "real-kitchen-ai.jsonl"]) {
    it(`${name}: parsea, produce eventos y ningun modelo vacio/synthetic`, () => {
      const events = extractUsageEvents(read(name));
      expect(events.length).toBeGreaterThan(0);
      expect(events.every((e) => e.model && e.model !== "<synthetic>")).toBe(true);
      expect(events.every((e) => /^\d{4}-\d{2}-\d{2}$/.test(e.day))).toBe(true);
    });
  }
});

describe("ClaudeCodeAdapter.parseSession", () => {
  it("normaliza una sesion con id, agent y project derivados de la ruta", async () => {
    const adapter = new ClaudeCodeAdapter();
    const session = await adapter.parseSession(fx("deterministic.jsonl"));
    expect(session.id).toBe("deterministic");
    expect(session.agent).toBe("claude-code");
    expect(session.project).toBe("fixtures");
    expect(session.events).toHaveLength(4);
  });
});

import { describe, it, expect } from "vitest";
import { costForEvent } from "../src/lib/cost.js";
import { getRate, UnknownModels, type Pricing } from "../src/lib/pricing.js";
import type { UsageEvent } from "../src/adapters/types.js";

const pricing: Pricing = {
  models: {
    "claude-opus-4-8": { input: 5.0, output: 25.0 },
  },
};

function ev(partial: Partial<UsageEvent>): UsageEvent {
  return {
    sessionId: "s",
    ts: "2026-07-01T00:00:00.000Z",
    day: "2026-07-01",
    model: "claude-opus-4-8",
    input: 0,
    output: 0,
    cacheWrite: 0,
    cacheRead: 0,
    ...partial,
  };
}

describe("costForEvent", () => {
  it("aplica la formula §2: in*5 + out*25 + cacheW*5*1.25 + cacheR*5*0.10 por millon", () => {
    // 1M de cada tipo con opus: 5 + 25 + 6.25 + 0.5 = 36.75
    const rate = getRate(pricing, "claude-opus-4-8")!;
    const cost = costForEvent(
      ev({ input: 1_000_000, output: 1_000_000, cacheWrite: 1_000_000, cacheRead: 1_000_000 }),
      rate,
    );
    expect(cost).toBeCloseTo(36.75, 6);
  });

  it("solo input", () => {
    const rate = getRate(pricing, "claude-opus-4-8")!;
    expect(costForEvent(ev({ input: 2_000_000 }), rate)).toBeCloseTo(10.0, 6);
  });

  it("modelo desconocido (rate null) => costo 0", () => {
    expect(costForEvent(ev({ input: 1_000_000, model: "claude-ghost-9" }), null)).toBe(0);
  });
});

describe("getRate + UnknownModels", () => {
  it("registra modelos sin tarifa y devuelve null", () => {
    const unknown = new UnknownModels();
    expect(getRate(pricing, "claude-ghost-9", unknown)).toBeNull();
    expect(getRate(pricing, "claude-opus-4-8", unknown)).not.toBeNull();
    expect(unknown.list()).toEqual(["claude-ghost-9"]);
    expect(unknown.size).toBe(1);
  });
});

import { describe, it, expect, beforeAll } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { extractUsageEvents } from "../src/adapters/claude-code.js";
import { aggregate } from "../src/lib/aggregate.js";
import { loadPricing, type Pricing } from "../src/lib/pricing.js";
import type { NormalizedSession } from "../src/adapters/types.js";

const here = dirname(fileURLToPath(import.meta.url));
const read = (name: string) => readFileSync(join(here, "fixtures", name), "utf8");

function sessionFrom(name: string, jsonl: string): NormalizedSession {
  return { id: name, agent: "claude-code", project: "fixtures", events: extractUsageEvents(jsonl) };
}

describe("aggregate — tabla gasto/modelo/dia", () => {
  let pricing: Pricing;
  beforeAll(async () => {
    pricing = await loadPricing(); // usa data/pricing.json real
  });

  it("agrega por (dia, modelo) con costos correctos y ordena por dia/modelo", () => {
    const sessions = [sessionFrom("deterministic", read("deterministic.jsonl"))];
    const { rows, total, unknownModels } = aggregate(sessions, pricing);

    expect(rows.map((r) => `${r.day} ${r.model}`)).toEqual([
      "2026-07-01 claude-ghost-9",
      "2026-07-01 claude-haiku-4-5",
      "2026-07-01 claude-opus-4-8",
      "2026-07-02 claude-opus-4-8",
    ]);

    const byKey = Object.fromEntries(rows.map((r) => [`${r.day} ${r.model}`, r]));
    expect(byKey["2026-07-01 claude-opus-4-8"].costUsd).toBeCloseTo(36.75, 6);
    expect(byKey["2026-07-01 claude-haiku-4-5"].costUsd).toBeCloseTo(1.0, 6);
    expect(byKey["2026-07-01 claude-ghost-9"].costUsd).toBe(0); // sin tarifa
    expect(byKey["2026-07-02 claude-opus-4-8"].costUsd).toBeCloseTo(25.0, 6);

    // total = 36.75 + 1.00 + 0 + 25.00 = 62.75
    expect(total.costUsd).toBeCloseTo(62.75, 6);
    expect(unknownModels).toEqual(["claude-ghost-9"]);
  });

  it("criterio §7: suma por fila == total (±$0.01)", () => {
    const sessions = [sessionFrom("deterministic", read("deterministic.jsonl"))];
    const { rows, total } = aggregate(sessions, pricing);
    const sumRows = rows.reduce((n, r) => n + r.costUsd, 0);
    expect(Math.abs(sumRows - total.costUsd)).toBeLessThanOrEqual(0.01);
  });

  it("archivo sin usage no aporta filas", () => {
    const sessions = [sessionFrom("zero", read("zero-usage.jsonl"))];
    const { rows, total } = aggregate(sessions, pricing);
    expect(rows).toHaveLength(0);
    expect(total.costUsd).toBe(0);
  });

  it("fixtures reales anonimizados: costo total >= 0 y sin modelos desconocidos (todos en pricing)", () => {
    const sessions = [
      sessionFrom("printer", read("real-printer-android.jsonl")),
      sessionFrom("kitchen", read("real-kitchen-ai.jsonl")),
    ];
    const { total, unknownModels } = aggregate(sessions, pricing);
    expect(total.costUsd).toBeGreaterThan(0);
    expect(unknownModels).toEqual([]);
  });
});

