import { describe, it, expect, beforeAll, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, copyFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { openDb } from "../src/lib/db.js";
import { ingestAll } from "../src/ingest.js";
import { getSummary } from "../src/lib/summary.js";
import { loadPricing, type Pricing } from "../src/lib/pricing.js";
import type { DB } from "../src/lib/db.js";

const here = dirname(fileURLToPath(import.meta.url));
const fixture = (name: string) => join(here, "fixtures", name);

let tmp: string;
let pricing: Pricing;

/** Crea projects/<proj>/<file>.jsonl copiando un fixture. */
function seedProject(root: string, proj: string, file: string, fromFixture: string) {
  const dir = join(root, proj);
  mkdirSync(dir, { recursive: true });
  copyFileSync(fixture(fromFixture), join(dir, file));
}

function countEvents(db: DB): number {
  return (db.prepare("SELECT COUNT(*) AS n FROM usage_events").get() as { n: number }).n;
}

beforeAll(async () => {
  pricing = await loadPricing();
});
beforeEach(() => {
  tmp = mkdtempSync(join(tmpdir(), "motor-test-"));
});
afterEach(() => {
  rmSync(tmp, { recursive: true, force: true });
});

function freshDb(): DB {
  return openDb(join(tmp, "motor.db"));
}

describe("ingestAll", () => {
  it("inserta solo eventos unicos del transcript (dedup por dedup_key)", async () => {
    seedProject(tmp, "proj-A", "s1.jsonl", "deterministic.jsonl");
    const db = freshDb();
    const summary = await ingestAll(db, { projectsRoot: join(tmp), pricing });
    // deterministic: opus d1 (triplicado->1), haiku d1, ghost d1, opus d2 = 4
    expect(summary.eventsInserted).toBe(4);
    expect(countEvents(db)).toBe(4);
    expect(summary.unknownModels).toEqual(["claude-ghost-9"]);
    db.close();
  });

  it("incremental: segunda pasada sin cambios no inserta nada", async () => {
    seedProject(tmp, "proj-A", "s1.jsonl", "deterministic.jsonl");
    const db = freshDb();
    await ingestAll(db, { projectsRoot: tmp, pricing });
    const second = await ingestAll(db, { projectsRoot: tmp, pricing });
    expect(second.eventsInserted).toBe(0);
    expect(second.filesChanged).toBe(0);
    expect(countEvents(db)).toBe(4);
    db.close();
  });

  it("incremental: lineas nuevas se agregan sin re-contar las viejas", async () => {
    const dir = join(tmp, "proj-A");
    mkdirSync(dir, { recursive: true });
    const path = join(dir, "s1.jsonl");
    const line = (id: string, model: string) =>
      JSON.stringify({
        type: "assistant", timestamp: "2026-07-01T09:00:00.000Z", sessionId: "s1", requestId: id,
        message: { id, model, usage: { input_tokens: 1000, output_tokens: 1000, cache_creation_input_tokens: 0, cache_read_input_tokens: 0 } },
      });
    writeFileSync(path, line("r1", "claude-opus-4-8") + "\n");
    const db = freshDb();
    const a = await ingestAll(db, { projectsRoot: tmp, pricing });
    expect(a.eventsInserted).toBe(1);
    // append una linea nueva
    writeFileSync(path, line("r1", "claude-opus-4-8") + "\n" + line("r2", "claude-opus-4-8") + "\n");
    const b = await ingestAll(db, { projectsRoot: tmp, pricing });
    expect(b.eventsInserted).toBe(1); // solo la nueva
    expect(countEvents(db)).toBe(2);
    db.close();
  });

  it("dedup cross-archivo: mismo dedup_key en dos sesiones cuenta una vez", async () => {
    seedProject(tmp, "proj-A", "one.jsonl", "deterministic.jsonl");
    seedProject(tmp, "proj-B", "two.jsonl", "deterministic.jsonl");
    const db = freshDb();
    const summary = await ingestAll(db, { projectsRoot: tmp, pricing });
    expect(countEvents(db)).toBe(4); // no 8
    expect(summary.eventsInserted).toBe(4);
    db.close();
  });
});

describe("getSummary sobre DB ingerida", () => {
  it("agrega gasto/tokens/actividad/racha correctamente", async () => {
    seedProject(tmp, "proj-A", "s1.jsonl", "deterministic.jsonl");
    const db = freshDb();
    await ingestAll(db, { projectsRoot: tmp, pricing });
    const s = getSummary(db, pricing);

    expect(s.to).toBe("2026-07-02"); // ultimo dia con datos
    expect(s.totalCostUsd).toBeCloseTo(62.75, 6); // 36.75 + 1 + 0 + 25
    expect(s.activity.turns).toBe(4);
    expect(s.activity.projects).toBe(1);
    expect(s.streakDays).toBe(2); // 07-01 y 07-02 consecutivos
    expect(s.unknownModels).toEqual(["claude-ghost-9"]);

    const opus = s.perModel.find((m) => m.model === "claude-opus-4-8")!;
    expect(opus.costUsd).toBeCloseTo(61.75, 6); // 36.75 + 25
    const ghost = s.perModel.find((m) => m.model === "claude-ghost-9")!;
    expect(ghost.costUsd).toBe(0);
    expect(ghost.known).toBe(false);

    // criterio §7: suma por modelo == total (±0.01)
    const sumModels = s.perModel.reduce((n, m) => n + m.costUsd, 0);
    expect(Math.abs(sumModels - s.totalCostUsd)).toBeLessThanOrEqual(0.01);
    db.close();
  });

  it("DB vacia => summary con ceros y sin lanzar", async () => {
    const db = freshDb();
    const s = getSummary(db, pricing);
    expect(s.totalCostUsd).toBe(0);
    expect(s.daily).toEqual([]);
    expect(s.streakDays).toBe(0);
    db.close();
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { readFileSync, mkdtempSync, mkdirSync, copyFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { parseSkillUsages } from "../src/adapters/claude-code.js";
import { openDb, type DB } from "../src/lib/db.js";
import { ingestAll } from "../src/ingest.js";
import { getSkills, type CatalogEntry } from "../src/lib/skills.js";
import { loadConfig, saveConfig, DEFAULT_CONFIG, type Config } from "../src/lib/config.js";

const here = dirname(fileURLToPath(import.meta.url));
const fx = (name: string) => join(here, "fixtures", name);

describe("parseSkillUsages", () => {
  const usages = parseSkillUsages(readFileSync(fx("skills.jsonl"), "utf8"));

  it("detecta command-name en eventos user (con y sin command-args)", () => {
    const caveman = usages.filter((u) => u.skill === "caveman");
    expect(caveman).toHaveLength(2);
    expect(caveman[0].kind).toBe("command");
  });

  it("detecta comando nativo /model", () => {
    expect(usages.some((u) => u.skill === "model" && u.kind === "command")).toBe(true);
  });

  it("detecta Skill tool_use en assistant", () => {
    const fd = usages.find((u) => u.skill === "frontend-design");
    expect(fd?.kind).toBe("skill-tool");
  });
});

describe("ingest + getSkills", () => {
  let tmp: string;
  const catalog = new Map<string, CatalogEntry>([
    ["caveman", { name: "caveman", description: "modo caveman", category: "skill" }],
    ["other-skill", { name: "other-skill", description: "", category: "skill" }],
  ]);

  beforeEach(() => {
    tmp = mkdtempSync(join(tmpdir(), "motor-sk-"));
    const dir = join(tmp, "proj");
    mkdirSync(dir, { recursive: true });
    copyFileSync(fx("skills.jsonl"), join(dir, "sk.jsonl"));
  });
  afterEach(() => rmSync(tmp, { recursive: true, force: true }));

  async function seed(): Promise<DB> {
    const db = openDb(join(tmp, "motor.db"));
    // pricing default del repo
    const { loadPricing } = await import("../src/lib/pricing.js");
    await ingestAll(db, { projectsRoot: tmp, pricing: await loadPricing() });
    return db;
  }

  it("skills_usage no se duplica en re-ingesta", async () => {
    const db = await seed();
    const before = (db.prepare("SELECT COUNT(*) AS n FROM skills_usage").get() as { n: number }).n;
    const { loadPricing } = await import("../src/lib/pricing.js");
    await ingestAll(db, { projectsRoot: tmp, pricing: await loadPricing() });
    const after = (db.prepare("SELECT COUNT(*) AS n FROM skills_usage").get() as { n: number }).n;
    expect(after).toBe(before);
    expect(before).toBe(4); // caveman x2, model, frontend-design
    db.close();
  });

  it("agrega usos y calcula savedUsd = usos·min·tarifa/60", async () => {
    const db = await seed();
    const config: Config = { ...DEFAULT_CONFIG, hourlyRate: 120, minutesPerUseDefault: 5 };
    const { skills } = getSkills(db, config, catalog);
    const byName = Object.fromEntries(skills.map((s) => [s.name, s]));

    // caveman: 2 usos · 5 min · $120/h / 60 = $20
    expect(byName["caveman"].uses).toBe(2);
    expect(byName["caveman"].savedUsd).toBeCloseTo(20, 6);
    expect(byName["caveman"].category).toBe("skill");
    expect(byName["caveman"].inCatalog).toBe(true);

    // /model = builtin => categoria sistema
    expect(byName["model"].category).toBe("sistema");
    // frontend-design (Skill tool_use) no esta en el catalogo de prueba => otro
    expect(byName["frontend-design"].category).toBe("otro");
    // skill del catalogo sin uso aparece en gris (uses 0)
    expect(byName["other-skill"].uses).toBe(0);
    expect(byName["other-skill"].savedUsd).toBe(0);
    db.close();
  });

  it("tarifa/hora 0 => ahorro 0 (como capturas)", async () => {
    const db = await seed();
    const { skills } = getSkills(db, { ...DEFAULT_CONFIG, minutesPerUseDefault: 30 }, catalog);
    expect(skills.every((s) => s.savedUsd === 0)).toBe(true);
    db.close();
  });
});

describe("config round-trip", () => {
  let tmp: string;
  beforeEach(() => {
    tmp = mkdtempSync(join(tmpdir(), "motor-cfg-"));
  });
  afterEach(() => rmSync(tmp, { recursive: true, force: true }));

  it("saveConfig hace merge y loadConfig lo recupera", async () => {
    const path = join(tmp, "config.json");
    const saved = await saveConfig({ hourlyRate: 90, minutesPerUse: { caveman: 8 } }, path);
    expect(saved.hourlyRate).toBe(90);
    expect(saved.staleDays).toBe(DEFAULT_CONFIG.staleDays); // default preservado
    const loaded = await loadConfig(path);
    expect(loaded.hourlyRate).toBe(90);
    expect(loaded.minutesPerUse.caveman).toBe(8);
  });

  it("loadConfig sin archivo => defaults sin lanzar", async () => {
    const loaded = await loadConfig(join(tmp, "no-existe.json"));
    expect(loaded).toEqual(DEFAULT_CONFIG);
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { scanMemory } from "../src/lib/memory.js";

let tmp: string;
let root: string;

beforeEach(() => {
  tmp = mkdtempSync(join(tmpdir(), "motor-mem-"));
  root = join(tmp, "projects");
  const mem = join(root, "projX", "memory");
  mkdirSync(mem, { recursive: true });
  writeFileSync(
    join(mem, "a.md"),
    `---\nname: a\ndescription: uno\nmetadata:\n  node_type: memory\n  type: project\n  originSessionId: sess-1\n---\n\nvéase [[b]] para detalles.\n`,
  );
  writeFileSync(
    join(mem, "b.md"),
    `---\nname: b\ndescription: dos\nmetadata:\n  type: feedback\n---\n\ncontenido b.\n`,
  );
  writeFileSync(join(mem, "MEMORY.md"), `# Memory Index\n- [a](a.md) — uno\n- [b](b.md) — dos\n`);
});
afterEach(() => rmSync(tmp, { recursive: true, force: true }));

describe("scanMemory", () => {
  it("cuenta memorias y arma nodos por tipo", async () => {
    const g = await scanMemory(root);
    expect(g.counts.memories).toBe(2);
    const kinds = g.nodes.reduce<Record<string, number>>((a, n) => ({ ...a, [n.kind]: (a[n.kind] ?? 0) + 1 }), {});
    expect(kinds.memory).toBe(2);
    expect(kinds.index).toBe(1);
    expect(kinds.session).toBe(1); // sess-1 (origin)
    expect(kinds.project).toBe(1);
    const a = g.nodes.find((n) => n.label === "a")!;
    expect(a.type).toBe("project");
  });

  it("arista reference por wikilink [[b]] y arista origin por originSessionId", async () => {
    const g = await scanMemory(root);
    const ref = g.links.find((l) => l.rel === "reference");
    expect(ref?.source.endsWith("a.md")).toBe(true);
    expect(ref?.target.endsWith("b.md")).toBe(true);
    expect(g.links.some((l) => l.rel === "origin" && l.target === "session:sess-1")).toBe(true);
  });

  it("índice MEMORY.md contiene a las memorias del proyecto", async () => {
    const g = await scanMemory(root);
    const contains = g.links.filter((l) => l.rel === "contains" && l.source.endsWith("MEMORY.md"));
    expect(contains.length).toBe(2);
  });

  it("obsoleto: stale=true si mtime supera el umbral", async () => {
    const fresh = await scanMemory(root, { staleDays: 30 });
    expect(fresh.counts.stale).toBe(0);
    // simula 'ahora' 40 días en el futuro: los archivos recién creados quedan obsoletos.
    const future = Date.now() + 40 * 86_400_000;
    const aged = await scanMemory(root, { staleDays: 30, now: future });
    expect(aged.counts.stale).toBe(2);
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, copyFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { openDb, type DB } from "../src/lib/db.js";
import { ingestAll } from "../src/ingest.js";
import { getActivity, getSessionDetail } from "../src/lib/activity.js";
import { loadPricing } from "../src/lib/pricing.js";

const here = dirname(fileURLToPath(import.meta.url));
const fx = (name: string) => join(here, "fixtures", name);

let tmp: string;
let db: DB;

beforeEach(async () => {
  tmp = mkdtempSync(join(tmpdir(), "motor-act-"));
  const dir = join(tmp, "projX", "memory"); // sin memoria, pero crea proj dir
  mkdirSync(join(tmp, "projX"), { recursive: true });
  void dir;
  copyFileSync(fx("deterministic.jsonl"), join(tmp, "projX", "sesion1.jsonl"));
  db = openDb(join(tmp, "motor.db"));
  await ingestAll(db, { projectsRoot: tmp, pricing: await loadPricing() });
});
afterEach(() => {
  db.close();
  rmSync(tmp, { recursive: true, force: true });
});

describe("getActivity", () => {
  it("agrupa sesiones por día (ended_at), más reciente primero", () => {
    const days = getActivity(db);
    // la sesión terminó el 2026-07-02 (max ts de deterministic)
    expect(days[0].day).toBe("2026-07-02");
    expect(days[0].sessions).toHaveLength(1);
    const s = days[0].sessions[0];
    expect(s.id).toBe("sesion1");
    expect(s.project).toBe("projX");
    expect(s.turns).toBe(4);
    expect(s.models).toContain("claude-opus-4-8");
  });
});

describe("getSessionDetail", () => {
  it("desglosa tokens/costo por modelo", () => {
    const d = getSessionDetail(db, "sesion1")!;
    expect(d).not.toBeNull();
    const models = d.models.map((m) => m.model).sort();
    expect(models).toEqual(["claude-ghost-9", "claude-haiku-4-5", "claude-opus-4-8"]);
    // total = 36.75 + 1 + 0 + 25 = 62.75
    expect(d.totalCostUsd).toBeCloseTo(62.75, 6);
    const ghost = d.models.find((m) => m.model === "claude-ghost-9")!;
    expect(ghost.costUsd).toBe(0);
  });

  it("sesión inexistente => null", () => {
    expect(getSessionDetail(db, "no-existe")).toBeNull();
  });
});

