/** Modelo normalizado compartido por todos los adapters (PLAN §1.3). */

export interface UsageEvent {
  sessionId: string;
  ts: string; // ISO 8601
  day: string; // YYYY-MM-DD (derivado de ts)
  model: string;
  input: number;
  output: number;
  cacheWrite: number; // cache_creation_input_tokens
  cacheRead: number; // cache_read_input_tokens
}

export interface NormalizedSession {
  id: string;
  agent: string; // "claude-code", "codex", ...
  project: string;
  events: UsageEvent[];
}

export interface SkillUsage {
  skill: string;
  ts: string;
  kind: "command" | "skill-tool";
}

/**
 * Acceso SOLO LECTURA a las fuentes (PLAN §0). Se abre siempre con flag 'r':
 * nunca crea ni trunca. Toda escritura vive en ./data (state.ts / config / etc).
 */
import { readFile, readdir } from "node:fs/promises";
import type { Dirent } from "node:fs";

/** Lee un archivo de una fuente read-only. Flag 'r' => falla si no existe, jamás escribe. */
export function readFileRO(path: string): Promise<string> {
  return readFile(path, { encoding: "utf8", flag: "r" });
}

/** Lista un directorio de una fuente read-only. */
export function readDirRO(path: string): Promise<Dirent[]> {
  return readdir(path, { withFileTypes: true });
}

/**
 * SQLite vía node:sqlite (sin deps nativas, PLAN §3). La DB es un caché
 * reconstruible en ./data/motor.db — el schema se crea si no existe.
 */
import { DatabaseSync } from "node:sqlite";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

export type DB = DatabaseSync;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS sessions (
  id          TEXT PRIMARY KEY,
  agent       TEXT NOT NULL,
  project     TEXT NOT NULL,
  started_at  TEXT,
  ended_at    TEXT,
  turns       INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS usage_events (
  dedup_key           TEXT PRIMARY KEY,
  session_id          TEXT NOT NULL,
  ts                  TEXT NOT NULL,
  day                 TEXT NOT NULL,
  model               TEXT NOT NULL,
  input_tokens        INTEGER NOT NULL,
  output_tokens       INTEGER NOT NULL,
  cache_write_tokens  INTEGER NOT NULL,
  cache_read_tokens   INTEGER NOT NULL,
  cost_usd            REAL NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_usage_day   ON usage_events(day);
CREATE INDEX IF NOT EXISTS idx_usage_model ON usage_events(model);
CREATE TABLE IF NOT EXISTS skills_usage (
  skill                   TEXT NOT NULL,
  session_id              TEXT NOT NULL,
  ts                      TEXT NOT NULL,
  kind                    TEXT NOT NULL DEFAULT 'command',
  minutes_saved_estimated REAL,
  UNIQUE(skill, session_id, ts, kind)
);
CREATE INDEX IF NOT EXISTS idx_skills_skill ON skills_usage(skill);
CREATE TABLE IF NOT EXISTS memory_nodes (
  path           TEXT PRIMARY KEY,
  name           TEXT,
  project        TEXT,
  type           TEXT,
  size           INTEGER,
  last_touched   TEXT,
  origin_session TEXT,
  stale_bool     INTEGER
);
CREATE TABLE IF NOT EXISTS ingest_offsets (
  path        TEXT PRIMARY KEY,
  size        INTEGER NOT NULL,
  mtime_ms    INTEGER NOT NULL,
  line_count  INTEGER NOT NULL,
  updated_at  TEXT NOT NULL
);
`;

/** Abre (o crea) la DB en `path` y asegura el schema. */
export function openDb(path: string): DB {
  const db = new DatabaseSync(path);
  db.exec("PRAGMA journal_mode = WAL;");
  db.exec(SCHEMA);
  return db;
}

/** Ruta por defecto de la DB: ./data/motor.db en la raíz del repo. */
export function defaultDbPath(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  return join(here, "..", "..", "data", "motor.db");
}

/**
 * Motor de costos "equivalente API" (PLAN §2). Tarifas en USD por millón de
 * tokens. cache_write = 1.25× input, cache_read = 0.10× input.
 */
import type { UsageEvent } from "../adapters/types.js";
import type { Rate } from "./pricing.js";

const PER_MILLION = 1_000_000;

/** Costo de un evento. rate null (modelo sin tarifa) => 0, nunca se estima. */
export function costForEvent(ev: UsageEvent, rate: Rate | null): number {
  if (!rate) return 0;
  return (
    (ev.input * rate.input +
      ev.output * rate.output +
      ev.cacheWrite * rate.input * 1.25 +
      ev.cacheRead * rate.input * 0.1) /
    PER_MILLION
  );
}

/**
 * Tarifas editables (./data/pricing.json). Modelo sin tarifa => null + registro
 * en UnknownModels (badge visible en UI). Nunca se estima en silencio (PLAN §2).
 */
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { readFileRO } from "./fs-readonly.js";

export interface Rate {
  input: number;
  output: number;
}

export interface Pricing {
  models: Record<string, Rate>;
  verified_at?: string;
  source_url?: string;
  note?: string;
}

function defaultPricingPath(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  return join(here, "..", "..", "data", "pricing.json");
}

export async function loadPricing(path = defaultPricingPath()): Promise<Pricing> {
  const raw = await readFileRO(path);
  const p = JSON.parse(raw) as Pricing;
  if (!p.models || typeof p.models !== "object") throw new Error("pricing.json inválido: falta 'models'");
  return p;
}

export async function savePricing(pricing: Pricing, path = defaultPricingPath()): Promise<Pricing> {
  if (!pricing.models || typeof pricing.models !== "object") {
    throw new Error("pricing inválido: falta 'models'");
  }
  await writeFile(path, JSON.stringify(pricing, null, 2) + "\n", "utf8");
  return pricing;
}

/** Acumula los modelos vistos sin tarifa, únicos y en orden de aparición. */
export class UnknownModels {
  private seen = new Set<string>();
  add(model: string): void {
    this.seen.add(model);
  }
  list(): string[] {
    return [...this.seen];
  }
  get size(): number {
    return this.seen.size;
  }
}

/** Tarifa del modelo o null (registrándolo en `unknown` si se pasa). */
export function getRate(pricing: Pricing, model: string, unknown?: UnknownModels): Rate | null {
  const rate = pricing.models[model];
  if (rate) return rate;
  unknown?.add(model);
  return null;
}

/**
 * Adapter Claude Code (PLAN §1.1). Transcripts JSONL en
 * ~/.claude/projects/<proj>/<session>.jsonl. Cada línea es un evento; los
 * `assistant` traen message.model + message.usage. SOLO LECTURA.
 *
 * Reglas: dedup por (message.id + requestId), se excluye model "<synthetic>",
 * las líneas corruptas se saltan sin lanzar, modelo desconocido se conserva
 * (la tarifa se decide después, en el motor de costos).
 */
import { homedir } from "node:os";
import { basename, dirname, join } from "node:path";
import { readFileRO, readDirRO } from "../lib/fs-readonly.js";
import type { NormalizedSession, SkillUsage, UsageEvent } from "./types.js";

export function defaultProjectsRoot(): string {
  return join(homedir(), ".claude", "projects");
}

interface ParsedLine {
  dedupKey: string;
  event: UsageEvent;
}

function splitLines(raw: string): string[] {
  const parts = raw.split("\n");
  // Descarta el "" final que deja el newline de cierre, para que el offset
  // incremental no se descoloque al re-leer.
  return parts.length && parts[parts.length - 1] === "" ? parts.slice(0, -1) : parts;
}

function toParsedLine(o: any, fallbackKey: string): ParsedLine | null {
  if (!o || o.type !== "assistant") return null;
  const m = o.message;
  if (!m || !m.usage) return null;
  const model: string | undefined = m.model;
  if (!model || model === "<synthetic>") return null;

  const u = m.usage;
  const ts = String(o.timestamp ?? m.timestamp ?? "");
  const event: UsageEvent = {
    sessionId: String(o.sessionId ?? ""),
    ts,
    day: ts.slice(0, 10),
    model,
    input: u.input_tokens ?? 0,
    output: u.output_tokens ?? 0,
    cacheWrite: u.cache_creation_input_tokens ?? 0,
    cacheRead: u.cache_read_input_tokens ?? 0,
  };
  const idKey = `${m.id ?? ""}::${o.requestId ?? ""}`;
  const dedupKey = m.id || o.requestId ? idKey : fallbackKey;
  return { dedupKey, event };
}

/**
 * Parsea las líneas desde `fromLine` (para ingesta incremental). Dedup dentro
 * del slice por dedupKey. `lineCount` = líneas físicas del archivo (offset).
 */
export function parseTranscriptLines(
  raw: string,
  fromLine = 0,
): { events: ParsedLine[]; lineCount: number } {
  const lines = splitLines(raw);
  const events: ParsedLine[] = [];
  const seen = new Set<string>();
  for (let i = fromLine; i < lines.length; i++) {
    const t = lines[i].trim();
    if (!t) continue;
    let o: any;
    try {
      o = JSON.parse(t);
    } catch {
      continue; // línea corrupta => se salta
    }
    const parsed = toParsedLine(o, `noid::${i}`);
    if (!parsed) continue;
    if (seen.has(parsed.dedupKey)) continue;
    seen.add(parsed.dedupKey);
    events.push(parsed);
  }
  return { events, lineCount: lines.length };
}

/** Eventos de uso únicos de un transcript completo. */
export function extractUsageEvents(raw: string): UsageEvent[] {
  return parseTranscriptLines(raw).events.map((e) => e.event);
}

const COMMAND_RE = /<command-name>\/?([\w.:-]+)<\/command-name>/;

/** Detecta uso de skills/comandos: /nombre en user + tool_use Skill en assistant. */
export function parseSkillUsages(raw: string, fromLine = 0): SkillUsage[] {
  const lines = splitLines(raw);
  const out: SkillUsage[] = [];
  for (let i = fromLine; i < lines.length; i++) {
    const t = lines[i].trim();
    if (!t) continue;
    let o: any;
    try {
      o = JSON.parse(t);
    } catch {
      continue;
    }
    const ts = String(o.timestamp ?? "");
    if (o.type === "user") {
      const c = o.message?.content;
      const text = typeof c === "string" ? c : JSON.stringify(c ?? "");
      const mm = text.match(COMMAND_RE);
      if (mm) out.push({ skill: mm[1], ts, kind: "command" });
    } else if (o.type === "assistant" && Array.isArray(o.message?.content)) {
      for (const b of o.message.content) {
        if (b?.type === "tool_use" && b.name === "Skill" && b.input?.skill) {
          const skill = String(b.input.skill).split(":").pop() as string;
          out.push({ skill, ts, kind: "skill-tool" });
        }
      }
    }
  }
  return out;
}

export class ClaudeCodeAdapter {
  readonly id = "claude-code";
  constructor(private root: string = defaultProjectsRoot()) {}

  /** Rutas de todos los transcripts .jsonl bajo projects/<proj>/. */
  async discoverSessions(): Promise<string[]> {
    let projects;
    try {
      projects = await readDirRO(this.root);
    } catch {
      return []; // no hay ~/.claude/projects
    }
    const paths: string[] = [];
    for (const p of projects) {
      if (!p.isDirectory()) continue;
      const dir = join(this.root, p.name);
      let files;
      try {
        files = await readDirRO(dir);
      } catch {
        continue;
      }
      for (const f of files) {
        if (f.isFile() && f.name.endsWith(".jsonl")) paths.push(join(dir, f.name));
      }
    }
    return paths.sort();
  }

  async parseSession(path: string): Promise<NormalizedSession> {
    const raw = await readFileRO(path);
    return {
      id: basename(path, ".jsonl"),
      agent: this.id,
      project: basename(dirname(path)),
      events: extractUsageEvents(raw),
    };
  }
}

/** Agregación gasto/modelo/día para el CLI de Fase 1 (PLAN §6-F1). */
import type { NormalizedSession } from "../adapters/types.js";
import { costForEvent } from "./cost.js";
import { getRate, UnknownModels, type Pricing } from "./pricing.js";

export interface Row {
  day: string;
  model: string;
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
  costUsd: number;
}

export interface Totals {
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
  costUsd: number;
}

export function aggregate(
  sessions: NormalizedSession[],
  pricing: Pricing,
): { rows: Row[]; total: Totals; unknownModels: string[] } {
  const unknown = new UnknownModels();
  const byKey = new Map<string, Row>();

  for (const s of sessions) {
    for (const e of s.events) {
      const key = `${e.day}�${e.model}`;
      let r = byKey.get(key);
      if (!r) {
        r = { day: e.day, model: e.model, input: 0, output: 0, cacheWrite: 0, cacheRead: 0, costUsd: 0 };
        byKey.set(key, r);
      }
      r.input += e.input;
      r.output += e.output;
      r.cacheWrite += e.cacheWrite;
      r.cacheRead += e.cacheRead;
      r.costUsd += costForEvent(e, getRate(pricing, e.model, unknown));
    }
  }

  const rows = [...byKey.values()].sort((a, b) =>
    a.day !== b.day ? a.day.localeCompare(b.day) : a.model.localeCompare(b.model),
  );

  const total: Totals = { input: 0, output: 0, cacheWrite: 0, cacheRead: 0, costUsd: 0 };
  for (const r of rows) {
    total.input += r.input;
    total.output += r.output;
    total.cacheWrite += r.cacheWrite;
    total.cacheRead += r.cacheRead;
    total.costUsd += r.costUsd;
  }

  return { rows, total, unknownModels: unknown.list() };
}

/**
 * Config del usuario (./data/config.json): tarifa/hora, min ahorrados por uso,
 * umbral de obsolescencia, rutas de agentes (PLAN §4.5). loadConfig hace merge
 * sobre defaults; nunca lanza si falta el archivo.
 */
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { readFileRO } from "./fs-readonly.js";

export interface Config {
  hourlyRate: number;
  staleDays: number;
  minutesPerUseDefault: number;
  minutesPerUse: Record<string, number>;
  agentPaths: Record<string, string>;
}

export const DEFAULT_CONFIG: Config = {
  hourlyRate: 0,
  staleDays: 30,
  minutesPerUseDefault: 0,
  minutesPerUse: {},
  agentPaths: {},
};

function defaultConfigPath(): string {
  const here = dirname(fileURLToPath(import.meta.url));
  return join(here, "..", "..", "data", "config.json");
}

function merge(partial: Partial<Config>): Config {
  return {
    ...DEFAULT_CONFIG,
    ...partial,
    minutesPerUse: { ...DEFAULT_CONFIG.minutesPerUse, ...(partial.minutesPerUse ?? {}) },
    agentPaths: { ...DEFAULT_CONFIG.agentPaths, ...(partial.agentPaths ?? {}) },
  };
}

export async function loadConfig(path = defaultConfigPath()): Promise<Config> {
  try {
    return merge(JSON.parse(await readFileRO(path)) as Partial<Config>);
  } catch {
    return { ...DEFAULT_CONFIG }; // sin archivo => defaults
  }
}

/** Merge del parcial sobre lo existente (o defaults) y persiste. */
export async function saveConfig(partial: Partial<Config>, path = defaultConfigPath()): Promise<Config> {
  const current = await loadConfig(path);
  const next = merge({
    ...current,
    ...partial,
    minutesPerUse: { ...current.minutesPerUse, ...(partial.minutesPerUse ?? {}) },
    agentPaths: { ...current.agentPaths, ...(partial.agentPaths ?? {}) },
  });
  await writeFile(path, JSON.stringify(next, null, 2) + "\n", "utf8");
  return next;
}

/**
 * Resumen de la página Inicio (PLAN §4.1): gasto equiv. de la ventana + serie
 * diaria, actividad (turnos, Δ% 7d, proyectos), racha de días activos y
 * participación por modelo. Lee de la DB ya ingerida.
 */
import type { DB } from "./db.js";
import type { Pricing } from "./pricing.js";

const DEFAULT_WINDOW_DAYS = 28;
const DAY_MS = 86_400_000;

export interface DailyPoint {
  day: string;
  costUsd: number;
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
}

export interface ModelShare {
  model: string;
  costUsd: number;
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
  known: boolean;
  share: number; // fracción del costo total de la ventana
}

export interface Summary {
  from?: string;
  to?: string;
  windowDays: number;
  totalCostUsd: number;
  totalTokens: number;
  daily: DailyPoint[];
  perModel: ModelShare[];
  activity: { turns: number; projects: number; deltaPct7d: number | null };
  streakDays: number;
  unknownModels: string[];
}

function addDays(day: string, delta: number): string {
  const d = new Date(day + "T00:00:00.000Z");
  return new Date(d.getTime() + delta * DAY_MS).toISOString().slice(0, 10);
}

function emptySummary(windowDays: number): Summary {
  return {
    windowDays,
    totalCostUsd: 0,
    totalTokens: 0,
    daily: [],
    perModel: [],
    activity: { turns: 0, projects: 0, deltaPct7d: null },
    streakDays: 0,
    unknownModels: [],
  };
}

export function getSummary(
  db: DB,
  pricing: Pricing,
  opts: { windowDays?: number } = {},
): Summary {
  const windowDays = opts.windowDays ?? DEFAULT_WINDOW_DAYS;
  const last = db.prepare("SELECT MAX(day) AS d FROM usage_events").get() as { d: string | null };
  if (!last.d) return emptySummary(windowDays);

  const to = last.d;
  const from = addDays(to, -(windowDays - 1));

  const daily = db
    .prepare(
      `SELECT day,
              SUM(cost_usd) AS costUsd,
              SUM(input_tokens) AS input, SUM(output_tokens) AS output,
              SUM(cache_write_tokens) AS cacheWrite, SUM(cache_read_tokens) AS cacheRead
       FROM usage_events WHERE day BETWEEN ? AND ? GROUP BY day ORDER BY day`,
    )
    .all(from, to) as DailyPoint[];

  const perModelRows = db
    .prepare(
      `SELECT model,
              SUM(cost_usd) AS costUsd,
              SUM(input_tokens) AS input, SUM(output_tokens) AS output,
              SUM(cache_write_tokens) AS cacheWrite, SUM(cache_read_tokens) AS cacheRead
       FROM usage_events WHERE day BETWEEN ? AND ? GROUP BY model ORDER BY costUsd DESC`,
    )
    .all(from, to) as Omit<ModelShare, "known" | "share">[];

  const totalCostUsd = perModelRows.reduce((n, m) => n + m.costUsd, 0);
  const perModel: ModelShare[] = perModelRows.map((m) => ({
    ...m,
    known: !!pricing.models[m.model],
    share: totalCostUsd > 0 ? m.costUsd / totalCostUsd : 0,
  }));
  const unknownModels = perModel.filter((m) => !m.known).map((m) => m.model);
  const totalTokens = perModelRows.reduce(
    (n, m) => n + m.input + m.output + m.cacheWrite + m.cacheRead,
    0,
  );

  const turns = (
    db
      .prepare("SELECT COUNT(*) AS n FROM usage_events WHERE day BETWEEN ? AND ?")
      .get(from, to) as { n: number }
  ).n;
  const projects = (
    db
      .prepare(
        `SELECT COUNT(DISTINCT s.project) AS n FROM sessions s
         JOIN usage_events u ON u.session_id = s.id WHERE u.day BETWEEN ? AND ?`,
      )
      .get(from, to) as { n: number }
  ).n;

  // Δ% turnos: últimos 7 días vs los 7 previos.
  const last7From = addDays(to, -6);
  const prev7From = addDays(to, -13);
  const prev7To = addDays(to, -7);
  const cnt = (a: string, b: string) =>
    (db.prepare("SELECT COUNT(*) AS n FROM usage_events WHERE day BETWEEN ? AND ?").get(a, b) as {
      n: number;
    }).n;
  const last7 = cnt(last7From, to);
  const prev7 = cnt(prev7From, prev7To);
  const deltaPct7d = prev7 > 0 ? ((last7 - prev7) / prev7) * 100 : null;

  // Racha: días consecutivos con actividad terminando en `to`.
  const activeDays = new Set(
    (db.prepare("SELECT DISTINCT day FROM usage_events").all() as { day: string }[]).map((r) => r.day),
  );
  let streakDays = 0;
  for (let d = to; activeDays.has(d); d = addDays(d, -1)) streakDays++;

  return {
    from,
    to,
    windowDays,
    totalCostUsd,
    totalTokens,
    daily,
    perModel,
    activity: { turns, projects, deltaPct7d },
    streakDays,
    unknownModels,
  };
}

/**
 * Página Skills (PLAN §4.2). Cataloga ~/.claude/skills + commands (RO), cuenta
 * usos desde skills_usage y calcula $ ahorrado = usos·min·tarifa/60. Sin tarifa
 * (o sin minutos) => $0, como en las capturas de referencia.
 */
import { homedir } from "node:os";
import { join } from "node:path";
import { readFileRO, readDirRO } from "./fs-readonly.js";
import type { DB } from "./db.js";
import type { Config } from "./config.js";

export interface CatalogEntry {
  name: string;
  description: string;
  category: string;
}

export interface SkillRow {
  name: string;
  uses: number;
  lastUsed: string | null;
  category: string; // catálogo | "sistema" (builtin) | "otro"
  savedUsd: number;
  minutesPerUse: number;
  inCatalog: boolean;
}

// Comandos nativos de Claude Code => categoría "sistema" (no cuentan como skills).
const BUILTIN = new Set([
  "model", "clear", "help", "init", "review", "compact", "config", "cost",
  "memory", "doctor", "status", "resume", "mcp", "agents", "permissions",
  "hooks", "login", "logout", "bug", "ide", "vim", "terminal-setup",
  "pr-comments", "release-notes", "add-dir", "plugin", "reload-plugins", "fast",
]);

function frontmatter(raw: string): Record<string, string> {
  const m = raw.match(/^---\n([\s\S]*?)\n---/);
  if (!m) return {};
  const out: Record<string, string> = {};
  for (const line of m[1].split("\n")) {
    const kv = line.match(/^(\w[\w-]*):\s*(.*)$/);
    if (kv) out[kv[1]] = kv[2].trim().replace(/^["']|["']$/g, "");
  }
  return out;
}

/** Recorre skills/ y commands/ (RO) y arma el catálogo por nombre. */
export async function discoverCatalog(root = join(homedir(), ".claude")): Promise<Map<string, CatalogEntry>> {
  const catalog = new Map<string, CatalogEntry>();
  for (const [sub, category] of [["skills", "skill"], ["commands", "comando"]] as const) {
    const dir = join(root, sub);
    let entries;
    try {
      entries = await readDirRO(dir);
    } catch {
      continue;
    }
    for (const e of entries) {
      // Soporta tanto `commands/x.md` como `skills/x/SKILL.md`.
      const file = e.isDirectory() ? join(dir, e.name, "SKILL.md") : join(dir, e.name);
      if (!e.isDirectory() && !e.name.endsWith(".md")) continue;
      let raw: string;
      try {
        raw = await readFileRO(file);
      } catch {
        continue;
      }
      const fm = frontmatter(raw);
      const name = fm.name || e.name.replace(/\.md$/, "");
      catalog.set(name, { name, description: fm.description ?? "", category: fm.category || category });
    }
  }
  return catalog;
}

export function getSkills(
  db: DB,
  config: Config,
  catalog: Map<string, CatalogEntry>,
): { skills: SkillRow[]; categories: Record<string, number> } {
  const used = db
    .prepare(
      "SELECT skill, COUNT(*) AS uses, MAX(ts) AS lastUsed FROM skills_usage GROUP BY skill",
    )
    .all() as { skill: string; uses: number; lastUsed: string | null }[];

  const usesByName = new Map(used.map((r) => [r.skill, r]));
  const names = new Set<string>([...usesByName.keys(), ...catalog.keys()]);

  const skills: SkillRow[] = [];
  for (const name of names) {
    const u = usesByName.get(name);
    const uses = u?.uses ?? 0;
    const cat = catalog.get(name);
    const category = cat ? cat.category : BUILTIN.has(name) ? "sistema" : "otro";
    const minutesPerUse = config.minutesPerUse[name] ?? config.minutesPerUseDefault;
    const savedUsd = (uses * minutesPerUse * config.hourlyRate) / 60;
    skills.push({
      name,
      uses,
      lastUsed: u?.lastUsed ?? null,
      category,
      savedUsd,
      minutesPerUse,
      inCatalog: !!cat,
    });
  }

  skills.sort((a, b) => b.uses - a.uses || a.name.localeCompare(b.name));

  const categories: Record<string, number> = {};
  for (const s of skills) categories[s.category] = (categories[s.category] ?? 0) + s.uses;

  return { skills, categories };
}

/**
 * Grafo de memoria (PLAN §4.3). Escanea ~/.claude/projects/<proj>/memory/*.md
 * (SOLO LECTURA). Nodos: memoria / índice (MEMORY.md) / sesión (origin) /
 * proyecto. Aristas: reference ([[wikilink]] o link md), origin
 * (originSessionId), contains (índice → memorias). Obsoleto = mtime > umbral.
 */
import { stat } from "node:fs/promises";
import { basename, join } from "node:path";
import { readFileRO, readDirRO } from "./fs-readonly.js";
import { defaultProjectsRoot } from "../adapters/claude-code.js";

const DAY_MS = 86_400_000;

export type NodeKind = "memory" | "index" | "session" | "project";

export interface MemNode {
  id: string; // path del archivo, o "session:x" / "project:x"
  label: string;
  kind: NodeKind;
  project: string;
  type?: string; // metadata.type de la memoria
  size?: number;
  lastTouched?: string;
  stale?: boolean;
}

export interface MemLink {
  source: string;
  target: string;
  rel: "reference" | "origin" | "contains";
}

export interface MemoryGraph {
  nodes: MemNode[];
  links: MemLink[];
  counts: { memories: number; stale: number };
}

const clean = (s: string) => s.trim().replace(/^["']|["']$/g, "");

interface FrontMatter {
  name?: string;
  description?: string;
  type?: string;
  originSessionId?: string;
}

function parseFrontmatter(raw: string): FrontMatter {
  const m = raw.match(/^---\n([\s\S]*?)\n---/);
  const fm: FrontMatter = {};
  if (!m) return fm;
  let inMeta = false;
  for (const line of m[1].split("\n")) {
    const top = /^(\w[\w-]*):\s*(.*)$/.exec(line);
    if (top && !/^\s/.test(line)) {
      inMeta = top[1] === "metadata" && top[2].trim() === "";
      if (top[1] === "name") fm.name = clean(top[2]);
      else if (top[1] === "description") fm.description = clean(top[2]);
      continue;
    }
    if (inMeta) {
      const sub = /^\s+(\w[\w-]*):\s*(.*)$/.exec(line);
      if (sub?.[1] === "type") fm.type = clean(sub[2]);
      else if (sub?.[1] === "originSessionId") fm.originSessionId = clean(sub[2]);
    }
  }
  return fm;
}

export async function scanMemory(
  root: string = defaultProjectsRoot(),
  opts: { staleDays?: number; now?: number } = {},
): Promise<MemoryGraph> {
  const staleDays = opts.staleDays ?? 30;
  const now = opts.now ?? Date.now();
  const nodes: MemNode[] = [];
  const links: MemLink[] = [];
  const sessionIds = new Set<string>();

  let projects;
  try {
    projects = await readDirRO(root);
  } catch {
    return { nodes, links, counts: { memories: 0, stale: 0 } };
  }

  for (const p of projects) {
    if (!p.isDirectory()) continue;
    const memDir = join(root, p.name, "memory");
    let files;
    try {
      files = await readDirRO(memDir);
    } catch {
      continue; // proyecto sin memoria
    }
    const mdFiles = files.filter((f) => f.isFile() && f.name.endsWith(".md"));
    if (mdFiles.length === 0) continue;

    nodes.push({ id: `project:${p.name}`, label: p.name, kind: "project", project: p.name });

    // name -> path, para resolver [[wikilink]] dentro del proyecto.
    const byName = new Map<string, string>();
    const parsed: { path: string; raw: string; fm: FrontMatter; isIndex: boolean }[] = [];

    for (const f of mdFiles) {
      const path = join(memDir, f.name);
      const raw = await readFileRO(path);
      const fm = parseFrontmatter(raw);
      const isIndex = f.name === "MEMORY.md";
      const name = fm.name ?? basename(f.name, ".md");
      byName.set(name, path);
      parsed.push({ path, raw, fm, isIndex });

      const st = await stat(path);
      const stale = now - st.mtimeMs > staleDays * DAY_MS;
      nodes.push({
        id: path,
        label: name,
        kind: isIndex ? "index" : "memory",
        project: p.name,
        type: fm.type,
        size: st.size,
        lastTouched: new Date(st.mtimeMs).toISOString(),
        stale,
      });

      if (fm.originSessionId) {
        const sid = `session:${fm.originSessionId}`;
        if (!sessionIds.has(sid)) {
          sessionIds.add(sid);
          nodes.push({ id: sid, label: fm.originSessionId, kind: "session", project: p.name });
        }
        links.push({ source: path, target: sid, rel: "origin" });
      }
    }

    for (const { path, raw, isIndex } of parsed) {
      if (isIndex) {
        // Índice: link markdown [texto](archivo.md) => contains.
        for (const m of raw.matchAll(/\[[^\]]+\]\(([^)]+\.md)\)/g)) {
          const target = join(memDir, m[1]);
          if (byName.size && [...byName.values()].includes(target)) {
            links.push({ source: path, target, rel: "contains" });
          }
        }
      } else {
        // Memoria: [[nombre]] => reference al archivo de ese nombre.
        for (const m of raw.matchAll(/\[\[([^\]]+)\]\]/g)) {
          const target = byName.get(clean(m[1]));
          if (target && target !== path) links.push({ source: path, target, rel: "reference" });
        }
      }
    }
  }

  const memoryNodes = nodes.filter((n) => n.kind === "memory");
  return {
    nodes,
    links,
    counts: { memories: memoryNodes.length, stale: memoryNodes.filter((n) => n.stale).length },
  };
}

/**
 * Página Actividad (PLAN §4.4): timeline de sesiones por día (según ended_at) y
 * drill-down por sesión con desglose de tokens/costo por modelo.
 */
import type { DB } from "./db.js";

export interface ActivitySession {
  id: string;
  project: string;
  agent: string;
  startedAt: string | null;
  endedAt: string | null;
  turns: number;
  costUsd: number;
  models: string[];
}

export interface ActivityDay {
  day: string;
  sessions: ActivitySession[];
}

export interface ModelBreakdown {
  model: string;
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
  costUsd: number;
}

export interface SessionDetail {
  id: string;
  project: string;
  agent: string;
  startedAt: string | null;
  endedAt: string | null;
  turns: number;
  totalCostUsd: number;
  models: ModelBreakdown[];
}

/** Sesiones agrupadas por día (día = substr de ended_at), más reciente primero. */
export function getActivity(db: DB): ActivityDay[] {
  const rows = db
    .prepare(
      `SELECT s.id, s.project, s.agent, s.started_at AS startedAt, s.ended_at AS endedAt, s.turns,
              COALESCE(SUM(u.cost_usd), 0) AS costUsd,
              GROUP_CONCAT(DISTINCT u.model) AS models
       FROM sessions s LEFT JOIN usage_events u ON u.session_id = s.id
       GROUP BY s.id ORDER BY s.ended_at DESC`,
    )
    .all() as (Omit<ActivitySession, "models"> & { models: string | null })[];

  const byDay = new Map<string, ActivityDay>();
  for (const r of rows) {
    const day = (r.endedAt ?? r.startedAt ?? "").slice(0, 10);
    if (!day) continue;
    let d = byDay.get(day);
    if (!d) {
      d = { day, sessions: [] };
      byDay.set(day, d);
    }
    d.sessions.push({ ...r, models: r.models ? r.models.split(",") : [] });
  }
  return [...byDay.values()].sort((a, b) => b.day.localeCompare(a.day));
}

export function getSessionDetail(db: DB, id: string): SessionDetail | null {
  const s = db
    .prepare(
      "SELECT id, project, agent, started_at AS startedAt, ended_at AS endedAt, turns FROM sessions WHERE id = ?",
    )
    .get(id) as Omit<SessionDetail, "totalCostUsd" | "models"> | undefined;
  if (!s) return null;

  const models = db
    .prepare(
      `SELECT model,
              SUM(input_tokens) AS input, SUM(output_tokens) AS output,
              SUM(cache_write_tokens) AS cacheWrite, SUM(cache_read_tokens) AS cacheRead,
              SUM(cost_usd) AS costUsd
       FROM usage_events WHERE session_id = ? GROUP BY model ORDER BY costUsd DESC`,
    )
    .all(id) as ModelBreakdown[];

  return { ...s, totalCostUsd: models.reduce((n, m) => n + m.costUsd, 0), models };
}
